import networkx as nx
import json
import os
import pandas as pd
from typing import Dict, List


def search_algorithm(src, dsts, G, num_partitions):
    """Solve a directed Steiner multicast MILP, with a greedy incumbent fallback."""
    topology = BroadCastTopology(src, dsts, num_partitions)
    unique = list(dict.fromkeys(dsts))
    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))
    valid = []
    for u, v, data in h.edges(data=True):
        try:
            c = float(data.get("cost"))
            if c >= 0:
                valid.append((u, v, c))
            else:
                h.remove_edge(u, v)
        except (TypeError, ValueError):
            h.remove_edge(u, v)
    if not unique or not valid:
        return topology

    # A deterministic feasible incumbent also handles unavailable scipy MILP.
    def greedy():
        out = {}
        used = set()
        for d in unique:
            try:
                p = nx.dijkstra_path(h, src, d, weight="cost")
            except (nx.NetworkXNoPath, nx.NodeNotFound):
                continue
            q = list(zip(p, p[1:]))
            # Re-route with already activated edges free, encouraging sharing.
            def w(a, b, z):
                return 0.0 if (a, b) in used else float(z["cost"])
            try:
                p = nx.dijkstra_path(h, src, d, weight=w)
                q = list(zip(p, p[1:]))
            except (nx.NetworkXNoPath, nx.NodeNotFound):
                pass
            out[d] = q
            used.update(q)
        return out

    fallback = greedy()
    reachable = [d for d in unique if d in fallback]
    if len(reachable) != len(unique):
        return topology
    try:
        import numpy as np
        from scipy.optimize import milp, Bounds, LinearConstraint
        from scipy.sparse import lil_matrix

        m, k = len(valid), len(reachable)
        n = m + m * k
        index = {(u, v): i for i, (u, v, _) in enumerate(valid)}
        A = lil_matrix((1 + k * (len(h) + m), n), dtype=float)
        lb = np.full(A.shape[0], -np.inf)
        ub = np.full(A.shape[0], np.inf)
        row = 0
        A[row, :m] = [c for _, _, c in valid]
        lb[row] = -np.inf
        row += 1
        for j, d in enumerate(reachable):
            for node in h.nodes:
                for i, (u, v, _) in enumerate(valid):
                    if u == node:
                        A[row, m + j * m + i] += 1
                    if v == node:
                        A[row, m + j * m + i] -= 1
                if node == src:
                    lb[row], ub[row] = 1, 1
                elif node == d:
                    lb[row], ub[row] = -1, -1
                else:
                    lb[row], ub[row] = 0, 0
                row += 1
            for i in range(m):
                A[row, m + j * m + i] = 1
                A[row, i] = -1
                ub[row] = 0
                row += 1

        c = np.r_[[cost for _, _, cost in valid], np.zeros(m * k)]
        res = milp(c, integrality=np.ones(n), bounds=Bounds(0, 1),
                   constraints=LinearConstraint(A.tocsr(), lb, ub),
                   options={"time_limit": 3.0})
        paths = {}
        if res.x is not None:
            for j, d in enumerate(reachable):
                chosen = {valid[i][:2] for i in range(m)
                          if res.x[m + j * m + i] > .5}
                cur, seen, path = src, set(), []
                while cur != d and cur not in seen:
                    seen.add(cur)
                    nxt = next((v for u, v in chosen if u == cur), None)
                    if nxt is None:
                        break
                    path.append((cur, nxt))
                    cur = nxt
                if cur == d:
                    paths[d] = path
        if len(paths) == len(reachable):
            fallback = paths
    except Exception:
        pass

    for d, pairs in fallback.items():
        edges = [[u, v, G[u][v]] for u, v in pairs]
        for part in range(num_partitions):
            topology.set_dst_partition_paths(d, part, list(edges))
    return topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]


class BroadCastTopology:
    def __init__(
        self,
        src: str,
        dsts: List[str],
        num_partitions: int = 4,
        paths: Dict[str, SingleDstPath] = None,
    ):
        self.src = src
        self.dsts = dsts
        self.num_partitions = num_partitions
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {
                dst: {str(i): None for i in range(num_partitions)}
                for dst in dsts
            }

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)


def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(
            os.path.join(current_dir, "profiles/throughput.csv")
        )
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(
            row["src_region"],
            row["dst_region"],
            cost=None,
            throughput=num_vms * row["throughput_sent"] / 1e9,
        )

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    no_cost_pairs = []
    for edge in G.edges.data():
        edge_src, edge_dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((edge_src, edge_dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G


def create_broadcast_topology(src: str, dsts: List[str], num_partitions: int = 4):
    return BroadCastTopology(src, dsts, num_partitions)


def run_search_algorithm(src: str, dsts: List[str], G, num_partitions: int):
    return search_algorithm(src, dsts, G, num_partitions)

